export function level(model: Model, time: number): number {
  let value = model.mean;
  for (const c of model.constituents) {
    const theta = angle(c.speed, time);
    value += c.a * Math.cos(theta) + c.b * Math.sin(theta);
  }
  return value;
export function gridExtrema(
  model: Model,
  start: number,
  hours: number,
  spacing: number,
): GridExtremum[] {
  const count = (hours * 60) / spacing;
  const values = Array.from({ length: count + 1 }, (_, j) =>
    level(model, (60 * start + j * spacing) / 60),
  );
  const extrema: GridExtremum[] = [];
  for (let j = 1; j < count; j++) {
    const previous = values[j - 1];
    const current = values[j];
    const next = values[j + 1];
    let kind: GridExtremum['kind'];
    if (previous < current && current > next) kind = 'high';
    else if (previous > current && current < next) kind = 'low';
    else continue;
    const delta = (previous - next) / (2 * (previous - 2 * current + next));
    extrema.push({
      kind,
      refinedMinute: 60 * start + j * spacing + delta * spacing,
      height: current - ((previous - next) * delta) / 4,
    });
  }
  return extrema;
function predictions(station: Fitted, params: Parameters) {
  const hourly = Array.from({ length: params.hours + 1 }, (_, i) =>
    level(station.model, params.start + i),
  );
  const raw = gridExtrema(station.model, params.start, params.hours, params.grid);
  const rawExtrema = raw.length;
  while (raw.length >= 2) {
    let pair = 0;
    let difference = Math.abs(raw[0].height - raw[1].height);
    for (let i = 1; i + 1 < raw.length; i++) {
      const candidate = Math.abs(raw[i].height - raw[i + 1].height);
      if (candidate < difference) {
        difference = candidate;
        pair = i;
      }
    }
    if (difference >= params.minRange) break;
    raw.splice(pair, 2);
  }
  const extrema: Extremum[] = raw.map((e) => {
    const minute = Math.floor(e.refinedMinute + 0.5);
    return {
      ...e,
      minute,
      day: Math.floor(minute / 1440),
      label: e.kind === 'high' ? 'LHW' : 'HLW',
    };
  });
